### Problem:
def create_tuple_from_string(string: str) -> tuple:
    """
    Given a string, create a tuple by splitting the string and converting each element into its corresponding type.

    Example:
    create_tuple_from_string('1, 2.3, True, (4+2j), abc') -> (1, 2.3, True, (4+2j), 'abc')

    Required Libraries: re

    Difficulty: Hard
    """

### Solution:


    import re

    elements = re.findall(r'\d+|[-+]?\d*\.\d+|\([-+]?\d+[-+]?[\d+]j\)|\w+', string)
    result = []

    for element in elements:
        if element.isdigit():
            result.append(int(element))
        elif element.isnumeric():
            result.append(float(element))
        elif re.match(r'\((-?\d+[-+]?[\d+]j)\)', element):
            result.append(complex(element))
        else:
            result.append(element)

    return tuple(result)

